// WF-2 primary delivery: LeadSimple REST API, POST /rest/deals.
//
// Supersedes ADR-4's file-based adapter (DECISIONS 2026-08-18). The ADR read
// its config from /home/node/.n8n/wgc/leadsimple-map.json, a bind mount left
// over from the abandoned VPS design. Railway has no bind mounts and the
// worker's /home/node/.n8n is wiped on every redeploy, so that file could
// never exist. An empty catch turned "my config is missing" into
// delivered_api:false, so every lead since 2026-07-22 silently took the
// email-parse fallback for four weeks. Config is env-only now, and an absent
// adapter is REPORTED, never swallowed.
//
// Contract verified live 2026-08-18 against api.leadsimple.com/rest:
//   POST /deals, Content-Type application/x-www-form-urlencoded,
//   Authorization: <raw key> (a Bearer prefix is also accepted),
//   201 -> { data: { id, link, ... } }
// LeadSimple calls a lead a "Deal". deal[pipeline_id] is the only required
// field. deal[accept_duplicates] defaults to false, so LeadSimple itself
// dedupes on email or phone.
//
// Env, and every one of these MUST exist on BOTH the n8n main and worker
// services (queue mode: the worker is what executes this):
//   LEADSIMPLE_REST_KEY     Settings > Integrations > REST API. NOT the Zapier
//                           key, which LeadSimple documents as Zapier-only.
//   LEADSIMPLE_PIPELINE_ID  Owner Leads
//   LEADSIMPLE_STAGE_ID     New Lead
//   LEADSIMPLE_SOURCE_NAME  created on first use via create_source_if_new
//   LEADSIMPLE_API_BASE     optional override; defaults to the live base
const item = $input.all()[0];
if (!item) throw new Error('WF-2 CRM node received no items');
const payload = item.json.payload;
const estimate = item.json.estimate || null;
if (!payload || !payload.submission_id) throw new Error('WF-2 called without a canonical payload');

const API_BASE = ($env.LEADSIMPLE_API_BASE || 'https://api.leadsimple.com/rest').replace(/\/+$/, '');
const KEY = $env.LEADSIMPLE_REST_KEY || '';
const PIPELINE_ID = $env.LEADSIMPLE_PIPELINE_ID || '';
const STAGE_ID = $env.LEADSIMPLE_STAGE_ID || '';
const SOURCE_NAME = $env.LEADSIMPLE_SOURCE_NAME || '';

function nv(v) { return v === null || v === undefined ? '' : String(v); }
function money(n) { return '$' + Math.round(n).toLocaleString('en-US'); }

// LeadSimple returns 400 validation errors in at least two different shapes,
// observed live 2026-08-18: { error: "deal[pipeline_id] is missing" } for a
// missing field, and an ARRAY OF OBJECTS for a bad pipeline id. Naive
// stringification turned the second into "[object Object],[object Object]",
// which would have been the entire content of the alert email. An unreadable
// alarm is barely better than no alarm, so flatten whatever shape arrives.
function describeError(e) {
  function flat(v) {
    if (v === null || v === undefined) return '';
    if (typeof v === 'string') return v;
    if (typeof v === 'number' || typeof v === 'boolean') return String(v);
    if (Array.isArray(v)) return v.map(flat).filter(Boolean).join('; ');
    if (typeof v === 'object') {
      if (v.error !== undefined) return flat(v.error);
      if (v.errors !== undefined) return flat(v.errors);
      if (v.message !== undefined) return flat(v.message);
      return Object.keys(v).map(function (k) { return k + ': ' + flat(v[k]); }).filter(Boolean).join('; ');
    }
    return String(v);
  }
  const res = e && e.response;
  // n8n has moved the response body between these across versions, and getting
  // it wrong means an unreadable alert, so check all of them.
  const body = res && (res.body !== undefined ? res.body
    : res.data !== undefined ? res.data : undefined);
  const parts = [];
  const fromBody = flat(body !== undefined ? body : (e && (e.error !== undefined ? e.error : undefined)));
  if (fromBody) parts.push(fromBody);
  const msg = String((e && e.message) || '');
  if (msg && msg.indexOf('[object Object]') === -1 && fromBody.indexOf(msg) === -1) parts.push(msg);
  const out = parts.join(' | ').replace(/\s+/g, ' ').trim();
  return (out || 'unknown error').slice(0, 500);
}

// The form stopped collecting a name when it went estimate-first (2026-07-22),
// so the deal title is the email local-part. This is the title Jon sees in his
// pipeline (his call, 2026-08-18). Zip is the fallback if email is ever absent.
function leadTitle(p) {
  const email = nv(p.email).trim();
  const at = email.indexOf('@');
  if (at > 0) return email.slice(0, at);
  return 'Rent estimate - ' + (nv(p.zip) || 'unknown zip');
}
const title = leadTitle(payload);

// Readable context on the deal. LeadSimple's create-deal endpoint has no
// external-id field, so submission_id in the comments is the only thread back
// to an n8n execution.
const commentLines = [
  'Rent analysis request from the wgcassetguide.com estimator.',
  'Zip: ' + nv(payload.zip),
  'Square footage: ' + nv(payload.sqft),
  'Bedrooms: ' + nv(payload.bedrooms),
];
if (estimate && typeof estimate.low === 'number' && typeof estimate.high === 'number') {
  commentLines.push('Estimate shown: ' + money(estimate.low) + ' to ' + money(estimate.high));
  if (estimate.meta && estimate.meta.source) commentLines.push('Estimate basis: ' + estimate.meta.source);
}
commentLines.push('Free guide requested: ' + (payload.ebook_opt_in ? 'yes' : 'no'));
commentLines.push('Submission: ' + payload.submission_id);
const comments = commentLines.join('\n');

// Kept as the fallback path. Labels now follow LeadSimple's documented
// template (Phone Number, Zip Code) instead of our own invented ones, and Name
// is populated, so the fallback has a chance of parsing where the old one had
// a blank Name and a blank Phone on every single send.
const emailText = [
  'Name: ' + title,
  'Email: ' + nv(payload.email),
  'Phone Number: ' + nv(payload.phone),
  'Zip Code: ' + nv(payload.zip),
  'Comments: ' + comments.replace(/\n/g, ' | '),
].join('\n');

const missing = [];
if (!KEY) missing.push('LEADSIMPLE_REST_KEY');
if (!PIPELINE_ID) missing.push('LEADSIMPLE_PIPELINE_ID');

let deliveredApi = false;
let crmError = '';
let dealId = '';
let dealLink = '';

if (missing.length) {
  // FAIL LOUD. This is the exact condition the old empty catch hid for a month.
  crmError = 'CRM config absent, missing env var(s): ' + missing.join(', ')
    + '. Set these on BOTH the n8n main and worker services, then Publish.';
} else {
  const pairs = [
    ['deal[pipeline_id]', PIPELINE_ID],
    ['deal[stage_id]', STAGE_ID],
    ['deal[name]', title],
    ['deal[source_id_or_name]', SOURCE_NAME],
    ['deal[create_source_if_new]', SOURCE_NAME ? 'true' : ''],
    ['deal[accept_duplicates]', 'false'],
    ['deal[comments]', comments],
    ['contact[email_addresses][]', payload.email],
    ['property[address_zip_code]', payload.zip],
    ['property[square_feet]', payload.sqft],
    ['property[num_bedrooms]', payload.bedrooms],
  ];
  // Never sent today (buildPayload hardcodes phone ''), wired so that adding a
  // phone field to the form needs no change here. Rails-style array-of-objects.
  if (payload.phone) {
    pairs.push(['contact[phone_numbers][][kind]', 'mobile']);
    pairs.push(['contact[phone_numbers][][phone]', payload.phone]);
  }
  if (estimate && typeof estimate.low === 'number' && typeof estimate.high === 'number') {
    pairs.push(['property[estimated_rent]', String(Math.round((estimate.low + estimate.high) / 2))]);
  }
  const body = pairs
    .filter(function (kv) { return kv[1] !== null && kv[1] !== undefined && String(kv[1]) !== ''; })
    .map(function (kv) { return encodeURIComponent(kv[0]) + '=' + encodeURIComponent(String(kv[1])); })
    .join('&');

  const backoff = [2000, 8000, 30000];
  for (let attempt = 0; attempt < 3 && !deliveredApi; attempt++) {
    try {
      const res = await this.helpers.httpRequest({
        method: 'POST',
        url: API_BASE + '/deals',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded', Authorization: KEY },
        body: body,
        returnFullResponse: true,
        timeout: 10000,
      });
      const parsed = typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
      const deal = parsed && parsed.data;
      // A 2xx with no id is NOT success. Without this the old failure mode
      // (reporting delivery we never confirmed) just moves to a new home.
      if (!deal || !deal.id) throw new Error('response carried no data.id');
      deliveredApi = true;
      crmError = '';
      dealId = String(deal.id);
      dealLink = nv(deal.link);
    } catch (e) {
      const status = Number((e.response && e.response.status) || e.statusCode || 0);
      const headers = (e.response && e.response.headers) || {};
      crmError = 'POST /deals failed' + (status ? ' (HTTP ' + status + ')' : '') + ': ' + describeError(e);
      // Only a 429, a timeout, a 5xx or a transport error can succeed on a
      // second attempt. A 400 or a 401 fails identically three times, which
      // delays the alert by 10s and spends account-wide quota to learn nothing.
      // The rate limit here is per ACCOUNT, shared with the client's other
      // integrations, so a pointless retry is not free.
      const retryable = status === 0 || status === 408 || status === 429 || status >= 500;
      if (!retryable) { crmError += ' [permanent, not retried]'; break; }
      if (attempt < 2) {
        // Honour the server's own backoff when it hands us one; a fixed
        // schedule can fight another caller sharing the same account quota.
        const retryAfter = Number(headers['x-ratelimit-retry-after']) || 0;
        const waitMs = retryAfter > 0 ? retryAfter * 1000 : backoff[attempt];
        await new Promise(function (r) { setTimeout(r, waitMs); });
      }
    }
  }
}

return [{ json: {
  delivered_api: deliveredApi,
  crm_error: crmError,
  crm_deal_id: dealId,
  crm_deal_link: dealLink,
  email_text: emailText,
  submission_id: payload.submission_id,
  lead_name: title,
} }];

// Record which path delivered (feeds WF-3 weekly export, instrument I1).
const fs = require('fs');
const METRICS = '/home/node/.n8n/wgc-metrics.json';
let m = { days: {} };
try { m = JSON.parse(fs.readFileSync(METRICS, 'utf8')); } catch (e) { /* first run */ }
const day = new Date().toISOString().slice(0, 10);
m.days[day] = m.days[day] || { submissions: 0, bots: 0, delivered_api: 0, delivered_email: 0 };
m.days[day][$('CRM API attempt (mapped)').first().json.delivered_api ? 'delivered_api' : 'delivered_email'] += 1;
fs.writeFileSync(METRICS, JSON.stringify(m));
return [{ json: { delivered: true, submission_id: $('CRM API attempt (mapped)').first().json.submission_id } }];
